def is_balanced_list(lst):
    n = len(lst)
    for i in range(n):
        before = sum(lst[:i])
        after = sum(lst[i+1:])
        if before == after:
            return True
    return False

def center_of_mass_index(lst):
    total = sum(lst)
    if total == 0:
        return -1
    weighted = sum(i * v for i, v in enumerate(lst))
    return round(weighted / total)

def split_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def split_at_first_negative(lst):
    for i, x in enumerate(lst):
        if x < 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def partition_even_odd_values(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def split_before_first_zero(lst):
    for i, x in enumerate(lst):
        if x == 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def split_into_runs_by_sign(lst):
    if not lst:
        return []
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    result = []
    current = [lst[0]]
    for x in lst[1:]:
        if sign(x) == sign(current[-1]):
            current.append(x)
        else:
            result.append(current)
            current = [x]
    result.append(current)
    return result

def split_by_parity_runs(lst):
    if not lst:
        return []
    result = []
    current = [lst[0]]
    for x in lst[1:]:
        if x % 2 == current[-1] % 2:
            current.append(x)
        else:
            result.append(current)
            current = [x]
    result.append(current)
    return result

def unzip_pairs(pairs):
    firsts = []
    seconds = []
    for p in pairs:
        firsts.append(p[0])
        seconds.append(p[1])
    return (firsts, seconds)

def zip_three(a, b, c):
    n = min(len(a), len(b), len(c))
    return [(a[i], b[i], c[i]) for i in range(n)]

def cumulative_range(lst):
    result = []
    cur_max = None
    cur_min = None
    for x in lst:
        if cur_max is None:
            cur_max = x
            cur_min = x
        else:
            cur_max = max(cur_max, x)
            cur_min = min(cur_min, x)
        result.append(cur_max - cur_min)
    return result

def index_of_first_new_max(lst):
    if not lst:
        return []
    result = [0]
    cur_max = lst[0]
    for i in range(1, len(lst)):
        if lst[i] > cur_max:
            result.append(i)
            cur_max = lst[i]
    return result

def alternating_sum_plus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += x if i % 2 == 0 else -x
    return total

def alternating_sum_minus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += -x if i % 2 == 0 else x
    return total

def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    diffs = [abs(lst[i + 1] - lst[i]) for i in range(len(lst) - 1)]
    total = 0
    for i, d in enumerate(diffs):
        total += d if i % 2 == 0 else -d
    return total
